cd /mnt/c/Projects/hermes-agent && python3 << 'EOF'
import json

with open('agents/AGENT_REGISTRY.json') as f:
    registry = json.load(f)

print("=" * 100)
print("HERMES AGENT FLEET — COMPLETE TOPOLOGY")
print("=" * 100)

# Build dependency graph
dependencies = {}
for agent, info in registry.items():
    deps = info.get('dependencies', [])
    if agent not in dependencies:
        dependencies[agent] = {
            'depends_on': deps,
            'depended_by': []
        }
    for dep in deps:
        if dep not in dependencies:
            dependencies[dep] = {'depends_on': [], 'depended_by': []}
        dependencies[dep]['depended_by'].append(agent)

# Sort by tier, then lane, then name
agents_by_tier = {}
for agent, info in registry.items():
    tier = info.get('tier', 99)
    if tier not in agents_by_tier:
        agents_by_tier[tier] = {}
    lane = info.get('lane', 'Z')
    if lane not in agents_by_tier[tier]:
        agents_by_tier[tier][lane] = []
    agents_by_tier[tier][lane].append(agent)

for tier in sorted(agents_by_tier.keys()):
    for lane in sorted(agents_by_tier[tier].keys()):
        agents_by_tier[tier][lane].sort()

# Print detailed report
for tier in sorted(agents_by_tier.keys()):
    print(f"\n{'TIER ' + str(tier):^100}")
    print("=" * 100)

    for lane in sorted(agents_by_tier[tier].keys()):
        print(f"\nLane {lane}:")
        print("-" * 100)

        for agent in agents_by_tier[tier][lane]:
            info = registry[agent]
            status = info.get('status', 'unknown')
            cron = info.get('cron', 'on_demand')
            authority = info.get('authority', 'observe_only')

            status_icon = "✓" if status == 'active' else ("◐" if status == 'shadow' else "✗")

            # Dependencies
            deps = dependencies[agent]['depends_on']
            depended = dependencies[agent]['depended_by']

            print(f"\n  {status_icon} {agent}")
            print(f"     Description: {info['description']}")
            print(f"     Cron: {cron:20} Authority: {authority:20} Status: {status}")

            if deps:
                print(f"     Depends on:  {', '.join(deps)}")
            if depended:
                print(f"     Required by: {', '.join(depended)}")

print("\n" + "=" * 100)
print("DEPENDENCY SUMMARY")
print("=" * 100)

# Root agents (no dependencies)
roots = [a for a in registry if not dependencies[a]['depends_on']]
print(f"\nRoot agents (no dependencies): {len(roots)}")
for agent in sorted(roots):
    print(f"  • {agent}")

# Leaf agents (not depended upon)
leaves = [a for a in registry if not dependencies[a]['depended_by']]
print(f"\nLeaf agents (not depended upon): {len(leaves)}")
for agent in sorted(leaves):
    print(f"  • {agent}")

# Critical path
critical = [a for a in registry if len(dependencies[a]['depended_by']) >= 2]
print(f"\nCritical path agents (depended on by 2+ agents): {len(critical)}")
for agent in sorted(critical):
    count = len(dependencies[agent]['depended_by'])
    print(f"  • {agent} (required by {count} agents)")

EOF

